package com.sora.splineroads.world;
import com.sora.splineroads.SplineRoads;import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;
import java.util.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;import net.minecraft.nbt.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraftforge.gametest.*;
/** Loads saved SR metadata and real marker tags into a separate flat GameTest world, then uses normal connect. */
@GameTestHolder("splineroads_203_connect") @PrefixGameTestTemplate(false)
public class Connection203GameTests {
 static List<CompoundTag> nodes(Path folder)throws Exception{var result=new ArrayList<CompoundTag>();try(var files=Files.list(folder)){for(var file:files.filter(p->p.toString().endsWith(".mca")).toList())try(var input=new RandomAccessFile(file.toFile(),"r")){
  int[] offsets=new int[1024];for(int i=0;i<1024;i++)offsets[i]=(input.readInt()>>>8)*4096;
  for(int off:offsets){if(off==0)continue;input.seek(off);int len=input.readInt(),compression=input.readUnsignedByte();if(len<1||len>16_777_216)continue;byte[] bytes=new byte[len-1];input.readFully(bytes);InputStream stream=new ByteArrayInputStream(bytes);if(compression==2)stream=new InflaterInputStream(stream);else if(compression==1)stream=new GZIPInputStream(stream);else if(compression!=3)continue;var tag=NbtIo.read(new DataInputStream(stream));for(Tag t:tag.getList("block_entities",Tag.TAG_COMPOUND)){var node=(CompoundTag)t;if(node.getString("id").equals("splineroads:road_node"))result.add(node.copy());}}
 }}return result;}
 @GameTest(template="empty",templateNamespace="splineroads_203_connect",timeoutTicks=24000)
 public static void ordinaryConnectionDoesNotRejectDistantRetainedEndpoint(GameTestHelper h)throws Exception{
  var level=h.getLevel();String source=System.getenv("SR202_NODE_SOURCE"),world=System.getenv("SR202_NODE_WORLD");h.assertTrue(source!=null&&world!=null,"Set SR202_NODE_SOURCE and SR202_NODE_WORLD to read-only snapshot and marker-world path");
  var data=RoadData.load(NbtIo.readCompressed(new File(source)).getCompound("data"));level.getDataStorage().set("splineroads",data);
  int markers=0;for(var tag:(System.getenv("SR203_NODE_TAGS")==null?nodes(Path.of(world,"region")):NbtIo.readCompressed(new File(System.getenv("SR203_NODE_TAGS"))).getList("Nodes",Tag.TAG_COMPOUND).stream().map(t->(CompoundTag)t).toList())){var pos=new BlockPos(tag.getInt("x"),tag.getInt("y"),tag.getInt("z"));level.getChunkAt(pos);level.setBlock(pos,SplineRoads.NODE.get().defaultBlockState(),3);var node=(NodeEntity)level.getBlockEntity(pos);node.load(tag);markers++;}
  var a=new BlockPos(-1015,-60,283);var b=new BlockPos(-759,-60,286);if("1".equals(System.getenv("SR203_REVERSE"))){var swap=a;a=b;b=swap;}var remote=new BlockPos(-400,-51,288);h.assertTrue(level.getBlockEntity(a) instanceof NodeEntity&&level.getBlockEntity(b) instanceof NodeEntity&&level.getBlockEntity(remote) instanceof NodeEntity,"actual saved markers missing");var remoteBefore=level.getBlockEntity(remote).saveWithFullMetadata();var snapshot=data.save(new CompoundTag());var nodeABefore=level.getBlockEntity(a).saveWithFullMetadata();var nodeBBefore=level.getBlockEntity(b).saveWithFullMetadata();
  var r=data.index.roads.get(UUID.fromString("6eba28a5-9151-4dfc-9e48-90bed33be612")).record;var s=RoadProfile.editable(r.settings());var o=s.options();o=o.lanePoints(LanePoints.Data.EMPTY).attachments(RoadAttachments.Data.EMPTY).ends(RoadTransitions.Ends.NONE).infrastructure(o.infrastructure().clearEdits()).lift(.5,0).route(o.routing().offset(0,0).controls(List.of()).through(false)).outsets(0,0).sides(RoadProfile.Side.AUTO,RoadProfile.Side.AUTO);s=new Settings(Mode.valueOf(System.getenv().getOrDefault("SR203_MODE","STRAIGHT")),s.style(),s.width(),s.thickness(),s.tension(),s.arcDegrees()).structure(s.structure()).options(o);
  boolean red="1".equals(System.getenv("SR202_NODE_EXPECT_LEGACY"));RoadRecord result=null;
  try{result=data.connect(level,null,a,b,s,null);}catch(IllegalArgumentException e){if(s.mode()==Mode.STRAIGHT&&e.getMessage().contains("接缝方向或坡度不连续")){h.assertTrue(data.save(new CompoundTag()).equals(snapshot),"rejected straight connection changed metadata");h.assertTrue(level.getBlockEntity(a).saveWithFullMetadata().equals(nodeABefore)&&level.getBlockEntity(b).saveWithFullMetadata().equals(nodeBBefore)&&level.getBlockEntity(remote).saveWithFullMetadata().equals(remoteBefore),"rejected straight connection changed markers");h.assertTrue(RoadWorkChunks.heldCount(level)==0,"rejected straight connection leaked tickets");System.out.println("SR203 STRAIGHT NEGATIVE PASS reversed="+System.getenv("SR203_REVERSE")+" actual angle mismatch rejected without writes");h.succeed();return;}if(!red||!e.getMessage().contains("道路范围内有其他端点：-400, -51, 288"))throw e;h.assertTrue(data.save(new CompoundTag()).equals(snapshot),"failed connect changed saved metadata");System.out.println("SR202 FULL CONNECT RED actual source markers="+markers+" error="+e.getMessage());h.succeed();return;}
  h.assertTrue(!red,"baseline unexpectedly accepted connection");h.assertTrue(s.mode()!=Mode.STRAIGHT,"non-tangent straight connection unexpectedly accepted");h.assertTrue(result!=null&&data.index.roads.containsKey(result.id()),"normal connect failed to create outer road");h.assertTrue(level.getBlockEntity(remote).saveWithFullMetadata().equals(remoteBefore),"remote real endpoint changed");h.assertTrue(data.index.roads.containsKey(UUID.fromString("23f0d1c1-dbe9-4b43-b442-a23ae699c665")),"upper saved road was lost");h.assertTrue(RoadWorkChunks.heldCount(level)==0,"normal connect leaked chunk tickets");System.out.println("SR202 FULL CONNECT GREEN source mode="+s.mode()+" reversed="+System.getenv("SR203_REVERSE")+" markers="+markers+" new="+result.id()+" totalRoads="+data.index.roads.size()+" distant node exact");h.succeed();
 }
}




